<article class="counselor-message" :class="message.role === 'user' ? 'counselor-message-user' : 'counselor-message-assistant'">
    <div class="mb-3 flex items-center gap-2 text-xs text-ink-500"><span class="flex size-6 items-center justify-center rounded-lg" :class="message.role === 'user' ? 'bg-surface-muted text-ink-600' : 'bg-brand-50 text-brand-700'"><x-icon name="sparkles" class="size-3.5" x-show="message.role !== 'user'" /><x-icon name="user" class="size-3.5" x-show="message.role === 'user'" /></span><span class="font-semibold text-ink-800" x-text="message.role === 'user' ? 'You' : 'UniGuide Counselor'"></span><time :datetime="message.timestamp" class="ml-auto text-[11px]" x-text="formatTime(message.timestamp)"></time></div>
    <template x-if="message.role === 'user'"><p class="whitespace-pre-wrap break-words text-sm leading-7 text-ink-900" x-text="message.content"></p></template>
    <template x-if="message.role !== 'user'"><div><p x-show="message.archived_unverified" class="mb-4 rounded-lg border border-warning-200 bg-warning-50 p-3 text-xs leading-relaxed text-warning-800">This response has no current source metadata. Treat factual claims as unverified.</p><div class="counselor-prose" x-html="message.html"></div></div></template>
    <template x-if="message.inline_cards?.length"><div class="mt-5 grid grid-cols-1 gap-3 min-[720px]:grid-cols-2"><template x-for="card in message.inline_cards" :key="card.id"><section class="rounded-2xl border border-border-default bg-white p-4"><div class="mb-3 flex items-center justify-between gap-2"><span class="text-[11px] font-semibold uppercase tracking-wider text-ink-500" x-text="card.sector"></span><span class="text-[11px] text-brand-700" x-text="humanize(card.verification_status)"></span></div><h3 class="font-heading text-sm font-bold leading-snug text-ink-950" x-text="card.name"></h3><p class="mt-1 text-xs text-ink-500" x-text="card.city + ', ' + card.province"></p><div class="mt-4 space-y-2"><template x-for="campus in card.campuses.slice(0, 2)" :key="campus.url"><a :href="campus.url" class="block rounded-lg bg-surface-subtle p-2.5 text-xs text-ink-700 hover:bg-brand-50"><span class="font-semibold" x-text="campus.name"></span><span class="mt-1 block text-ink-500" x-text="humanize(campus.status) + ' · Operating status: ' + humanize(campus.operating_status)"></span></a></template><details x-show="card.campuses.length > 2" class="rounded-lg border border-border-subtle p-2"><summary class="min-h-11 cursor-pointer py-3 text-xs font-semibold text-brand-700" x-text="'More campuses (' + (card.campuses.length - 2) + ')' "></summary><template x-for="campus in card.campuses.slice(2)" :key="campus.url"><a :href="campus.url" class="block min-h-11 rounded-lg px-2 py-3 text-xs text-ink-700 hover:bg-brand-50" x-text="campus.name"></a></template></details></div><dl class="mt-4 space-y-2 border-t border-border-subtle pt-3 text-xs"><div class="flex justify-between gap-3"><dt class="text-ink-500">Published fees</dt><dd class="text-right text-ink-700" x-text="card.fees"></dd></div><div class="flex justify-between gap-3"><dt class="text-ink-500">Admissions</dt><dd class="text-right text-ink-700" x-text="card.admissions"></dd></div><div class="flex justify-between gap-3"><dt class="text-ink-500">Eligibility</dt><dd class="text-right text-ink-700" x-text="card.eligibility"></dd></div></dl><div class="mt-4 flex flex-wrap items-center gap-3 border-t border-border-subtle pt-3"><a :href="card.profile_url" class="inline-flex min-h-11 items-center text-xs font-semibold text-brand-700">View university →</a><a :href="card.compare_url" class="ml-auto inline-flex min-h-11 items-center text-xs font-medium text-ink-600">Compare</a></div></section></template></div></template>
    <div class="mt-3 flex flex-wrap items-center gap-2"><button type="button" @click="copyMessage(message)" class="counselor-text-button" :aria-label="'Copy ' + (message.role === 'user' ? 'your message' : 'counselor response')" x-text="copiedId === message.id ? 'Copied' : 'Copy'"></button><button type="button" x-show="message.citations?.length" @click="showContext(message.id)" class="counselor-text-button text-brand-700" x-text="(message.citations?.length || 0) + ' sources'"></button><span x-show="message.status === 'failed'" class="text-xs text-error-700">Not sent</span></div>
    <template x-if="message.prompts?.length"><div class="mt-3 flex flex-wrap gap-2"><template x-for="prompt in message.prompts" :key="prompt"><button type="button" @click="usePrompt(prompt)" :disabled="sending" class="min-h-11 rounded-xl border border-border-default bg-surface px-3 py-2 text-left text-xs text-ink-700 transition-colors hover:border-brand-300 hover:text-brand-700 disabled:opacity-50" x-text="prompt"></button></template></div></template>
</article>
